import Foundation
import MapKit

struct SafetyMapLine: Identifiable {
    let id: String
    let name: String
    let context: String
    let coordinates: [CLLocationCoordinate2D]
    let geometrySource: String
    let sourceURL: URL?

    init(
        id: String,
        name: String,
        context: String,
        coordinates: [CLLocationCoordinate2D],
        geometrySource: String = "Existing map reference",
        sourceURL: URL? = nil
    ) {
        self.id = id
        self.name = name
        self.context = context
        self.coordinates = coordinates
        self.geometrySource = geometrySource
        self.sourceURL = sourceURL
    }
}

struct SchoolSafetyArea: Identifiable {
    let id: String
    let name: String
    let coordinate: CLLocationCoordinate2D
    let radiusMeters: CLLocationDistance
}

enum NearbySafetyContext {
    case restrictedTrail(SafetyMapLine)
    case schoolArea(SchoolSafetyArea)
    case cautionRoad(SafetyMapLine)
}

