    static func nearbyContext(to coordinate: CLLocationCoordinate2D?) -> NearbySafetyContext? {
        guard let coordinate else { return nil }

        if let trail = nearestLine(in: restrictedTrails, to: coordinate, toleranceMeters: 12) {
            let trailDistance = trail.distance(to: coordinate)
            let otherFacilityDistance = SammamishZones.all.map { $0.distance(to: coordinate) }.min() ?? .greatestFiniteMagnitude
            // Do not identify a restricted trail from a neighboring road or path.
            // Ambiguous, parallel facilities need a map selection, not a guess.
            if trailDistance + 8 < otherFacilityDistance {
                return .restrictedTrail(trail)
            }
        }

        if let school = schools.filter({ $0.contains(coordinate) }).min(by: {
            MKMapPoint($0.coordinate).distance(to: MKMapPoint(coordinate))
                < MKMapPoint($1.coordinate).distance(to: MKMapPoint(coordinate))
        }) {
            return .schoolArea(school)
        }

        if let road = nearestLine(in: cautionRoads, to: coordinate, toleranceMeters: 18) {
            return .cautionRoad(road)
        }

        return nil
    }

    private static func nearestLine(
        in lines: [SafetyMapLine],
        to coordinate: CLLocationCoordinate2D,
        toleranceMeters: CLLocationDistance
    ) -> SafetyMapLine? {
        lines
            .map { ($0, $0.distance(to: coordinate)) }
            .filter { $0.1 <= toleranceMeters }
            .min { $0.1 < $1.1 }?
            .0
    }

    private static func line(id: String, name: String, context: String, encoded: String) -> SafetyMapLine {
        SafetyMapLine(id: id, name: name, context: context, coordinates: decodePolyline(encoded))
    }

    private static func decodeStreetRows(_ rows: String) -> [SafetyMapLine] {
        rows.split(separator: "\n").map { row in
            let fields = row.split(separator: "\t", maxSplits: 3).map(String.init)
            precondition(fields.count == 4, "Invalid generated street row")
            return SafetyMapLine(
                id: fields[0],
                name: fields[1],
                context: fields[2],
                coordinates: decodePolyline(fields[3], precision: 1_000_000),
                geometrySource: streetGeometrySource,
                sourceURL: streetGeometrySourceURL
            )
        }
    }

    private static func decodePolyline(_ encoded: String, precision: Double = 100_000) -> [CLLocationCoordinate2D] {
        let scalars = encoded.unicodeScalars.map { Int($0.value) }
        var coordinates: [CLLocationCoordinate2D] = []
        var index = 0
        var latitude = 0
        var longitude = 0

        func nextDelta() -> Int? {
            var result = 0
            var shift = 0

            while index < scalars.count {
                let byte = scalars[index] - 63
                index += 1
                result |= (byte & 0x1F) << shift
                shift += 5
                if byte < 0x20 {
                    return (result & 1) == 1 ? ~(result >> 1) : (result >> 1)
                }
            }

            return nil
        }

        while let latitudeDelta = nextDelta(), let longitudeDelta = nextDelta() {
            latitude += latitudeDelta
            longitude += longitudeDelta
            coordinates.append(
                CLLocationCoordinate2D(
                    latitude: Double(latitude) / precision,
                    longitude: Double(longitude) / precision
                )
            )
        }

        return coordinates
    }
}

private extension SafetyMapLine {
    func distance(to coordinate: CLLocationCoordinate2D) -> CLLocationDistance {
        guard let first = coordinates.first else { return .greatestFiniteMagnitude }
        guard coordinates.count > 1 else {
            return MKMapPoint(first).distance(to: MKMapPoint(coordinate))
        }

        let point = MKMapPoint(coordinate)
        var minimumDistance = CLLocationDistance.greatestFiniteMagnitude

        for index in 0..<(coordinates.count - 1) {
            let start = MKMapPoint(coordinates[index])
            let end = MKMapPoint(coordinates[index + 1])
            let deltaX = end.x - start.x
            let deltaY = end.y - start.y
            let lengthSquared = (deltaX * deltaX) + (deltaY * deltaY)
            let projection = lengthSquared == 0
                ? 0
                : min(1, max(0, ((point.x - start.x) * deltaX + (point.y - start.y) * deltaY) / lengthSquared))
            let closest = MKMapPoint(x: start.x + projection * deltaX, y: start.y + projection * deltaY)
            minimumDistance = min(minimumDistance, point.distance(to: closest))
        }

        return minimumDistance
    }
}

private extension SchoolSafetyArea {
    func contains(_ coordinate: CLLocationCoordinate2D) -> Bool {
        MKMapPoint(self.coordinate).distance(to: MKMapPoint(coordinate)) <= radiusMeters
    }
}
